const nativeRotationFenceExists = `-- name: NativeRotationFenceExists :one
SELECT EXISTS (
    SELECT 1
    FROM native_rotation_operation o
    WHERE (
        o.current_lifetime_id = $1
        OR o.target_lifetime_id = $1
        OR o.current_home_ref = $2
        OR o.target_home_ref = $2
    )
      AND o.state NOT IN ('committed_retired', 'aborted_candidate_retired')
) AS fenced
`

type NativeRotationFenceExistsParams struct {
	LifetimeID pgtype.UUID `json:"lifetime_id"`
	HomeRef    pgtype.UUID `json:"home_ref"`
}

func (q *Queries) NativeRotationFenceExists(ctx context.Context, arg NativeRotationFenceExistsParams) (bool, error) {
	row := q.db.QueryRow(ctx, nativeRotationFenceExists, arg.LifetimeID, arg.HomeRef)
	var fenced bool
	err := row.Scan(&fenced)
	return fenced, err
}

